            // 7-1: tubo liso de plástico
            { const Re = 21.22 * 200 * 995.62 / (52.5 * 0.80); add('7-1', 'Re', 100600, Re, 0.005); add('7-1', 'f (tubo liso)', 0.0179, colebrookWhite(Re, 0), 0.03, 'Crane lee f en el diagrama de Moody'); }
            // 7-2: K desde Kv
