            const ppr = fam === 'PP' && /pp-?r/i.test(txtMat) ? 70 : null, tmax = [e.tmax, TMAX_FAM[fam], ppr].filter(x => x != null).reduce((m, x) => Math.min(m, x), Infinity), nf = FAM_MAT[fam], nc = CLASES_FLUIDO[clase];
