            renderizarVectorial(); actualizarPanelAvisos(); pintarRedimensionar();
            const nf = fallosActuales().size; aviso(`Aplicados ${n} cambio(s). ${nf ? nf + ' componente(s) siguen sin cumplir.' : 'Toda la red cumple.'}`, nf ? 'error' : 'ok');
