            let t = fila('Modelo', `<b>${esc(it.nombre)}</b>${it.fabricante ? ' · ' + esc(it.fabricante) : ''}`) + fila('Tipo', esc((TIPOS_BOMBA_LIB.find(x => x[0] === (p.bombaTipo || 'centrifuga')) || [, ''])[1]));
