        // ==================================================================================
        const POS_MARCA = { N: [0, -76], NE: [88, -48], E: [104, -6], SE: [88, 36], S: [0, 60], SO: [-88, 36], O: [-104, -6], NO: [-88, -48] };
        let accionesMarcas = {};
