            fila(!faltan.length, 'Cajetín completo', faltan.length ? 'Falta: ' + faltan.join(', ') : 'Nombre, plano nº, autor, fecha y revisión', faltan.length ? ['Completar', 'cerrarModalRed(); abrirDatosProyecto()'] : null);
