                fila(ley && lis, `Hoja ${h.id}: leyenda y listado de componentes`, [ley ? '' : 'falta la leyenda', lis ? '' : 'falta el listado'].filter(Boolean).join(' y ') || 'Presentes', ley && lis ? null : ['Añadir', `${ir} ${ley ? '' : 'colocarLeyenda();'} ${lis ? '' : 'insertarListado(0, 0);'}`]);
