                if (aj && el.caudal) { const hd = aj.H0 - aj.k * el.caudal * el.caudal; if (hd > 0) s += `<circle cx="${X(el.caudal)}" cy="${Y(aM(hd))}" r="4.5" fill="none" stroke="#16a34a" stroke-width="2"/>`; }
