            if (T < 40 && T >= -10 && T < (+proyecto.tAmbiente || 20)) { const c = T <= 0 ? 0 : T <= 10 ? 1 : 2; return RITE_FRIO.e[fila][c] + (exterior ? 20 : 0); }
