                const el = a.el, dt = datosTuberia(el), L = a.L, lam = +el.lambdaAisl > 0 ? +el.lambdaAisl : 0.040;
                const eMin = aislamientoRITE(dt.od, fl.T, ext), eMinLam = eMin ? espesorPorLambda(dt.od, eMin, lam) : 0;
